OLD_HELPER_PATH='smali_classes14/com/chiyang001/adfree/FeedFilter.smali'
OLD_HELPER_HASHES=set(['0304ed372a2d12e0f192b8b8c47f26568ceb64bc1bbaf7801c74a88e17a41dd0', '356e15c44b603386883204d59565d7ee2d021f3b734605546d03ef41dee4055a', 'c4ed2f03c48704dfb240a5a4eb4db5817db5abfac788abc22b2ab86c852d1cb6'])

def digest(content):return hashlib.sha256(content.encode('utf8')).hexdigest()
def main():
 # Validate all inputs before any mutation; accept only exact analyzed revisions.
 for entry in EXPECTED:
  path=DECODED/entry['path']
  if path.exists():
   value=digest(path.read_text(encoding='utf8'))
   allowed={entry['original_sha256'],entry['patched_sha256'],*entry.get('known_patched_sha256s',[])}
   assert value in allowed,('Unknown source hash',str(path),value)
  else:assert entry['original_sha256'] is None,('Missing class',str(path))
 old_helper=DECODED/OLD_HELPER_PATH
 if old_helper.exists():
  assert digest(old_helper.read_text(encoding='utf8')) in OLD_HELPER_HASHES,('Unknown old helper',str(old_helper))
 planned={}
 for patch in INSERTS:
  path=patch['path'];text=(DECODED/path).read_text(encoding='utf8');new=patch['replacement']
  if new not in text:
   candidates=[patch['original'],*patch['previous']]
   matches=[x for x in candidates if text.count(x)==1]
   assert len(matches)==1,(path,'Unexpected patch pattern')
   text=text.replace(matches[0],new)
  planned[path]=text
 for patch in METHODS:
  path=patch['path'];text=(DECODED/path).read_text(encoding='utf8');signature=patch['signature']
  pattern=re.compile(r'^('+re.escape(signature)+r')\n.*?^\.end method',re.M|re.S)
  matches=list(pattern.finditer(text));assert len(matches)==1,(path,signature)
  match=matches[0];new=signature+'\n    '+MARKER+'\n'+patch['code'].strip('\n')+'\n.end method'
  planned[path]=text[:match.start()]+new+text[match.end():]
 planned[EXPECTED[-1]['path']]=HELPER_SOURCE
 for entry in EXPECTED:
  assert digest(planned[entry['path']])==entry['patched_sha256'],('Unexpected planned hash',entry['path'])
 changes=[]
 for entry in EXPECTED:
  path=DECODED/entry['path'];new=planned[entry['path']]
  already=path.exists() and path.read_text(encoding='utf8')==new
  if not already:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(new,encoding='utf8',newline='\n')
  changes.append({'path':entry['path'],'original_sha256':entry['original_sha256'],'patched_sha256':entry['patched_sha256'],'already_applied':already,'operation':'patch existing class' if entry['original_sha256'] else 'add helper class',**({'class':entry['class'],'previous_path':OLD_HELPER_PATH} if 'class' in entry else {})})
 # Delete only the exact known old added helper, after the new helper is written.
 if old_helper.exists():
  assert old_helper.resolve()==(DECODED/'smali_classes14/com/chiyang001/adfree/FeedFilter.smali').resolve()
  assert digest(old_helper.read_text(encoding='utf8')) in OLD_HELPER_HASHES
  old_helper.unlink()
 for entry in EXPECTED:assert digest((DECODED/entry['path']).read_text(encoding='utf8'))==entry['patched_sha256']
 assert not old_helper.exists(),'Duplicate helper would break class loading'
 (ROOT/'analysis/common_patch_report.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2),encoding='utf8')
 (ROOT/'analysis/common_patch_hashes.json').write_text(json.dumps(EXPECTED,ensure_ascii=False,indent=2),encoding='utf8')
 print(json.dumps(changes,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
